#ifndef NCLGL_NCLGLKERNEL_H
#define NCLGL_NCLGLKERNEL_H

#include <string.h>
#include <vector>

#include "NCLGLPgrInValue.h"
#include "NCLGLUtils.h"

class NCLGLKernel {
    public:
        NCLGLKernel();
        ~NCLGLKernel(void);

        void init(std::string *name, std::vector<std::string> arrOutput,
                  uint8_t *drawMode, uint8_t *depthTest, uint8_t *blend,
                  std::string blendEquation, std::string blendSrcMode, std::string blendDstMode,
                  std::string header, std::string source,
                  std::vector<std::string> varname, std::vector<std::string> varnameC, std::vector<std::string> type, std::vector<std::string> expectedMode, int inValuesCount);
        std::string _precision;
        std::string version;

        std::string _name;
        bool enabled;
        uint8_t _depthTest;
        uint8_t _blend;
        GLuint _blendSrcMode;
        GLuint _blendDstMode;
        GLuint _blendEquation;

        bool viewSource;

        std::vector<std::string> _output;
        uint8_t _outputTempModes[20];
        NCLGLPgrInValue in_values[100];
        int _inValuesCount;

        std::string _head;
        std::string _source;

        GLuint pgr_kernel;
        GLint attr_VertexPos;
        GLint uBufferWidth;

        int fBufferLength;
        int fBufferCount;

        GLuint getEnumBlendMode(std::string *blendStr);
        std::string lines_header(NCLGLPgrInValue in_values[]);
        std::string get_global_id3_GLSLFunctionString();
        std::string get_global_id2_GLSLFunctionString();
        std::string lines_drawBuffersWriteInit_GL2();
        std::string lines_drawBuffersInit();
        std::string lines_drawBuffersWrite_GL2();
        void compile();
        void setKernelSource(std::string *name, std::vector<std::string> arrOutput,
                             uint8_t *drawMode, uint8_t *depthTest, uint8_t *blend,
                             std::string blendEquation, std::string blendSrcMode, std::string blendDstMode,
                             std::string header, std::string source,
                             std::vector<std::string> varname, std::vector<std::string> varnameC, std::vector<std::string> type, std::vector<std::string> expectedMode, int inValuesCount);

    private:
        int dd;
};

#endif //NCLGL_NCLGLKERNEL_H